Import ListNotations.
Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Ltac zto pc := repeat (lazymatch goal with |- evt _ _ (MS _ _ (Z_to_bv 64 pc) _ _ _ _) => fail | _ => zstep end).

Section CANSEC1. Context {rc : runConstT}.
Section Y4S33D.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m0 : fmem).
  Variables (DST dcap SS DT mtl tl lo : Z) (src : list Z) (cells : list deltX2) (cbs : list byte).
  Notation SP := (bv_unsigned sp).
  Notation n := (zlen src).
  Hypothesis TOK : x2_table_ok cells tl.
  Hypothesis ECB : cbs = firstn (Z.to_nat (4 * 2^tl)) (x2_bytes' cells).
  Hypothesis LCB : zlen cbs = 4 * 2^tl.
  Hypothesis MTL : 1 <= mtl <= 12.
  Hypothesis TLM : tl <= mtl.
  Hypothesis D0 : 0 <= DST.
  Hypothesis DP : 0 < dcap -> 8 <= DST.
  Hypothesis DC : 0 <= dcap < 2^32.
  Hypothesis DL : DST + dcap <= lo.
  Hypothesis S0 : 16 <= SS.
  Hypothesis SL : SS + n <= lo.
  Hypothesis NSM : n < 2^26.
  Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.
  Hypothesis DT0 : 0 < DT.
  Hypothesis CBL : DT + 4 + 4 * 2^tl <= lo.
  Hypothesis DJ1 : DT + 4 + 4 * 2^tl <= DST \/ DST + dcap <= DT.
  Hypothesis DJ3 : DST + dcap <= SS \/ SS + n <= DST.
  Hypothesis LOS : lo <= SP - 4096.
  Hypothesis SP16 : SP mod 16 = 0.
  Hypothesis SP47 : SP <= 2^47.

  Notation POST := (huf_dec_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc DST dcap lo m0).
  Notation YB l := (l ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 DST dcap SS DT mtl tl lo src cells cbs
                      TOK ECB LCB MTL TLM D0 DP DC DL S0 SL NSM BYS DT0 CBL DJ1 DJ3 LOS SP16 SP47) (only parsing).
  Notation X4F' mm spl bd4 := (X4F ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 DST dcap SS DT lo src cbs mm spl bd4).

  (* [comment removed for export] *)
  Variables (O3 L3 Q3 v32 v40 v56 v72 v96 v104 v112 v120 v136 v144 v152 c4 bc4 ptr4 st4 : Z) (j0 jp : list byte).
  Variables (y1 y10 y12 y16 y19 y20 y21 y22 y25 y27 : word).
  Hypothesis HL3 : 6 <= O3 /\ 1 <= L3 /\ O3 + L3 <= n.
  Hypothesis HQ3 : 0 < Q3 <= dcap.
  Notation SPL := (SPLY (DST + Q3) v32 v40 (tl + 256 * mtl) v56 tl v72 (SS + O3) (DT + 4) v96 v104 v112 v120 (SS + O3 + 8) v136 v144 v152 j0).
  Notation BD := (BD4 c4 bc4 ptr4 st4 jp).

  Notation ST pc mm t0 t1 t2 x8 x9 a1 a3 a4 a5 a7 x26 t3 t4 t5 t6 :=
    (MS (mkR y1 (Z_to_bv 64 (SP + -416)) gp tp t0 t1 t2 x8 x9 y10 a1 y12 a3 a4 a5 y16 a7
             (Z_to_bv 64 (DT + 4)) y19 y20 y21 y22 (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 (DST + Q3)) y25 x26 y27 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).

  (* [comment removed for export] *)
  Hypothesis CONT : forall mm (t0 t1 t2 x8 x9 a1 a3 a4 a5 a7 x26 t3 t4 t5 : word),
    X4F' mm SPL BD ->
    evt psegs POST (ST 0x17f8c mm t0 t1 t2 x8 x9 a1 a3 a4 a5 a7 x26 t3 t4 t5 (Z_to_bv 64 v72)).

  (* [comment removed for export] *)
  Notation CL pc mm q t0 t1 t2 x8 x9 a1 a3 a5 a7 x26 t3 t4 t5 t6 :=
    (ST pc mm t0 t1 t2 x8 x9 a1 a3 (Z_to_bv 64 (DST + q)) a5 a7 x26 t3 t4 t5 t6).

  (* [comment removed for export] *)
  Ltac xpack OUT LB :=
    split; [eexists; split; [exact OUT| rewrite ?Zupd_length; exact LB]|];
    repeat (split; [first [eassumption | eexists; eassumption]|]); first [eassumption | eexists; eassumption].

  (* [comment removed for export] *)
  Ltac x2cell :=
    lazymatch goal with |- context [Z_to_bv 64 (((bv_unsigned ?c ≪ ?b) mod 18446744073709551616) ≫ ?sh)] =>
      let v := fresh "v" in let EV := fresh "EV" in let VR := fresh "VR" in
      remember (((bv_unsigned c ≪ b) mod 18446744073709551616) ≫ sh) as v eqn:EV;
      assert (VR : 0 <= v < 2^tl)
        by (subst v; apply y4_idx_bound; [lia| apply bv_unsigned_in_range| first [reflexivity | apply Z.mod_small; lia | lia]]);
      clear EV end.

  Ltac x2rd v c EC :=
    lazymatch goal with CE : bytes_at psegs ?mm (DT + 4) cbs, SQ : 0 <= x2_seq c < 65536 |- _ =>
      let RC0 := fresh "RC" in let RC2 := fresh "RC" in let RC3 := fresh "RC" in let RCB := fresh "RC" in
      destruct (x2_cell_rd psegs mm (DT + 4) cells (Z.to_nat (4 * 2^tl)) v c ltac:(rewrite <- ECB; exact CE)
                  ltac:(lia) ltac:(lia) ltac:(lia) EC SQ) as (RC0 & RC2 & RC3 & RCB) end.

  Ltac x2c v c EC :=
    lazymatch goal with TCK : forall i, 0 <= i < 2^tl -> _, VR : 0 <= v < 2^tl |- _ =>
      remember (nth (Z.to_nat v) cells x2_default) as c eqn:EC;
      let SQ := fresh "SQ" in let NB := fresh "NB" in let LN := fresh "LN" in
      destruct (TCK v VR) as (SQ & NB & LN); rewrite <- EC in SQ, NB, LN end.

  Notation Y33 l := (YB l O3 L3 Q3 v32 v40 v56 v72 v96 v104 v112 v120 v136 v144 v152 c4 bc4 ptr4 st4 j0 jp
                       y1 y10 y12 y16 y19 y20 y21 y22 y25 y27 HL3 HQ3 CONT) (only parsing).

  (* [comment removed for export] *)
  Lemma y33_else : forall q pt bits mm (t0 t1 t2 x8 x9 a1 a3 a7 t3 t4 t5 t6 : word),
    X4F' mm SPL BD -> 0 <= q <= Q3 -> 0 <= pt -> (pt = 0 \/ pt + 8 <= L3) -> 0 <= bits < 2^31 ->
